head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**
 * @method
 * @name callWidgetFlash
 * @description desc
 * @param {string} flashFile desc
 * @param {string} flashParam desc
 * @param {string} flashHeight desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.callWidgetFlash = function(flashFile, flashParam, flashHeight) {
    var flashStr = "";
    flashStr += "<object id='chart' width='100%' height='" + flashHeight + "' codebase='http://fpdownload.macromedia.com/pub/shockwave/cabs/flash/swflash.cab#version=9,0,0,0'>";
    flashStr += "<param name='movie' value='" + flashFile + "' />";
    flashStr += "<param name='quality' value='high' />";
    flashStr += "<param name='bgcolor' value='#ffffff' />";
    flashStr += "<param name='flashvars' value='" + flashParam + "'/>";
    flashStr += "<param name='allowScriptAccess' value='always' />";
    flashStr += "<embed src='" + flashFile + "' quality='high' bgcolor='#ffffff' width='100%' height='" + flashHeight + "' name='chart' align='middle' play='true' loop='false' quality='high' allowScriptAccess='always' type='application/x-shockwave-flash' pluginspage='http://www.macromedia.com/go/getflashplayer'/>";
    flashStr += "</object>";
    return flashStr;
};
/**
 * @method
 * @name documentwrite
 * @description desc
 * @param {string} src desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.documentwrite = function(src) {
    document.write(src);
};
/**
 * @method
 * @name callWizardFlash
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.callWizardFlash = function() {
    var flashStr = "";
    flashStr += "<embed src='/img/flash/wizard.swf' quality='high' bgcolor='#ffffff' width='500' height='540' name='wizard' align='middle' play='true' loop='false' quality='high' allowScriptAccess='always' type='application/x-shockwave-flash' pluginspage='http://www.macromedia.com/go/getflashplayer'/>";
    return flashStr;
};
